  const [tone, setTone]             = useState(agentDef.tone ?? "formal");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [localExamples, setLocalExamples] = useState<AgentExample[]>(
    examples.length > 0 ? examples : [{ input: "", output: "" }]
  );

