        }),
      });
      if (!res.ok) throw new Error(await apiErrorMessage(res));
      const data = await res.json();
      setSteps(data.steps);
    } catch (err) {
      setStepsError(err instanceof Error ? err.message : "Failed to generate steps");
    } finally {
      setGeneratingSteps(false);
    }
  }

  // ── Output chip toggle ────────────────────────────────────────────────────

  function toggleOutput(id: string) {
    setSelectedOutputs((prev) => {
      const next = prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id];
      // Reset the remembered answer whenever the output type changes.
      clarificationKeyRef.current = next.join(",");
      clarificationAnswerRef.current = "";
      return next;
    });
  }

  // ── Commit current state to context ──────────────────────────────────────

  function commitState(extraInstruction = "") {
    const refinements = (agentDef.refinements ?? "") + extraInstruction;
    const nextDef: AgentDef = {
      inputType: inputDesc,
      outputType: selectedOutputs.join(", "),
      policyDocId: uploadedDoc ? "__uploaded__" : policyDocId,
      tone,
      refinements,
      agentInstructions: buildInstructions(inputDesc, selectedOutputs, tone, localExamples, filledSteps) + refinements,
    };
    setExamples(localExamples);
    setAgentDef(nextDef);
    setProcessSteps(filledSteps);
    return { agentDef: nextDef, processSteps: filledSteps, examples: localExamples };
  }

  // ── Test run ──────────────────────────────────────────────────────────────

  async function handleTest() {
    // Path C: no example outputs → check confidence once per output configuration.
    const hasAnyOutput = localExamples.some((e) => e.output.trim());
    const currentKey = selectedOutputs.join(",");
    const alreadyAnswered = clarificationKeyRef.current === currentKey && clarificationAnswerRef.current !== "";
    if (!hasAnyOutput && !clarification && !alreadyAnswered) {
      setCheckingConfidence(true);
      try {
        const res = await fetch("/api/estimate-confidence", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            input_type: inputDesc,
            output_type: selectedOutputs.join(", "),
            policy_doc_id: uploadedDoc ? "service_policy" : policyDocId,
            ...(uploadedDoc ? { policy_text_override: uploadedDoc.text } : {}),
          }),
        });
        if (res.ok) {
          const data = await res.json();
          if (data.confidence < 0.9 && data.clarification_question) {
            setClarification(data.clarification_question);
            setCheckingConfidence(false);
            return;
          }
        }
      } catch {}
      setCheckingConfidence(false);
    }
    // Re-apply the remembered answer on subsequent runs without re-asking.
    const extra = alreadyAnswered
      ? `\n\nUser clarification: ${clarificationAnswerRef.current}`
      : "";
    doTest(extra);
  }

  async function doTest(extraInstruction = "", answeredClarification?: string) {
    const { agentDef: committedDef } = commitState(extraInstruction);
    setTestRunning(true);
    setTestError(null);
    setTestResult(null);
    try {
      const res = await fetch("/api/run", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          complaint_text: testInput,
          policy_doc_id: uploadedDoc ? "service_policy" : policyDocId,
          agent_instructions: committedDef.agentInstructions,
          ...(uploadedDoc ? { policy_text_override: uploadedDoc.text } : {}),
        }),
      });
      if (!res.ok) throw new Error(await apiErrorMessage(res));
      const data = await res.json();
      setTestResult(data);
      setRunResult({ ...data, complaint_text: testInput });
      setMaxStep(1);
      setSaved(false); // mark unsaved after a new test run
    } catch (err) {
      setTestError(err instanceof Error ? err.message : "Unknown error");
    } finally {
      setTestRunning(false);
      setClarification(null);
      setClarificationAnswer("");
      if (answeredClarification !== undefined) {
        // Remember the answer so subsequent runs skip re-asking.
        clarificationKeyRef.current = selectedOutputs.join(",");
        clarificationAnswerRef.current = answeredClarification;
      }
    }
  }

  // ── Save agent ────────────────────────────────────────────────────────────

  function handleSave() {
    saveAgent(commitState());
    setSaved(true);
  }

  // ── Rate & Improve ────────────────────────────────────────────────────────

  function handleImprove() {
    commitState();
    router.push("/improve");
